+/*
+ * SMB2 over QUIC (MS-SMB2 section 2.1).
+ *
+ * When SMB2 is carried over QUIC (ALPN "smb"), the SMB2 messages are sent
+ * over a QUIC stream using the same "Direct TCP transport" framing as SMB2
+ * over TCP: each message is prefixed with a 4-byte header consisting of one
+ * zero byte followed by a 3-byte big-endian length that does not include the
+ * header itself. The QUIC dissector provides the reassembled stream and honors
+ * the desegmentation requests made here via tcp_dissect_pdus().
+ */
+#define SMB2_QUIC_HEADER_LEN 4
+
+static unsigned
+get_smb2_quic_pdu_len(packet_info *pinfo _U_, tvbuff_t *tvb, int offset, void *data _U_)
+{
+	return SMB2_QUIC_HEADER_LEN + tvb_get_ntoh24(tvb, offset + 1);
+}
+
+static int
+dissect_smb2_quic_pdu(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+	proto_tree *quic_tree;
+	proto_item *ti;
+	tvbuff_t   *smb2_tvb;
+
+	ti = proto_tree_add_item(tree, proto_smb2_quic, tvb, 0, SMB2_QUIC_HEADER_LEN, ENC_NA);
+	quic_tree = proto_item_add_subtree(ti, ett_smb2_quic);
+	proto_tree_add_item(quic_tree, hf_smb2_quic_length, tvb, 1, 3, ENC_BIG_ENDIAN);
+
+	smb2_tvb = tvb_new_subset_remaining(tvb, SMB2_QUIC_HEADER_LEN);
+	dissect_smb2(smb2_tvb, pinfo, tree, true);
+
+	return tvb_captured_length(tvb);
+}
+
+static int
+dissect_smb2_quic(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data)
+{
+	tcp_dissect_pdus(tvb, pinfo, tree, true, SMB2_QUIC_HEADER_LEN,
+			 get_smb2_quic_pdu_len, dissect_smb2_quic_pdu, data);
+	return tvb_captured_length(tvb);
+}
